  "aspectos": {
    "entidade": {
      "estado": "sustentado",
      "fonte_ids": ["CHANGE.D02", "N.SUP_MOTOR"],
      "justificativa": "A alteração identifica SUP_MOTOR e a fonte local o define como Fornecedor MotorTech.",
      "contexto_ids": []
    },
    "alvo": {
      "estado": "sustentado",
      "fonte_ids": ["CHANGE.D02", "N.SUP_MOTOR"],
      "justificativa": "A fonte local associa SUP_MOTOR à disponibilidade contratada do fornecedor; o comunicado altera essa disponibilidade, sustentando o alvo release_SUP_MOTOR.",
      "contexto_ids": []
    },
    "atributo": {
      "estado": "sustentado",
      "fonte_ids": ["CHANGE.D02", "N.SUP_MOTOR"],
      "justificativa": "O comunicado declara uma nova disponibilidade contratada, e a fonte local caracteriza a restrição do fornecedor como disponibilidade contratada.",
      "contexto_ids": []
    },
    "unidade": {
      "estado": "sustentado",
      "fonte_ids": ["CHANGE.D02"],
      "justificativa": "O comunicado especifica 25 dias corridos desde D0, correspondendo à unidade proposta.",
      "contexto_ids": []
    },
    "valor": {
      "estado": "insuficiente",
      "fonte_ids": ["CHANGE.D02"],
      "justificativa": "A magnitude 25 dias é declarada para a nova disponibilidade, mas sua vigência começa em D10. A proposta a associa a uma vigência iniciada em D0, para a qual essa magnitude não é aplicável.",
      "contexto_ids": []
    },
    "condicoes": {
      "estado": "nao_aplicavel",
      "fonte_ids": [],
      "justificativa": "A lista de condições da proposta está vazia.",
      "contexto_ids": []
    },
    "escopo": {
      "estado": "contradito",
      "fonte_ids": ["CHANGE.D02"],
      "justificativa": "O cadastro verificado vincula o evento ao projeto ALFA-AMPLIADO, versão 1.0.0, com vigência prospectiva desde D0. Porém, a fonte documental declara início de vigência em D10 e exclui expressamente a aplicação prospectiva desde D0. A referência D0 permanece apenas como origem do calendário de disponibilidade.",
      "contexto_ids": ["CONTEXTO.ESCOPO"]
    }
  },
  "fontes_examinadas": ["CHANGE.D02", "E001", "N.SUP_MOTOR", "P.p_10"],
  "justificativa": "A alteração contratual sustenta a nova magnitude de 25 dias corridos para SUP_MOTOR, mas não com a vigência proposta: o comunicado só produz efeitos desde D10 e exclui sua aplicação desde D0. Essa divergência documental contradiz o escopo; E001 registra apenas precedência e não altera a restrição local, e P.p_10 trata de uma obrigação monetária sem relação com a alteração avaliada.",
  "suporte_ausente": [
    "Não há suporte para aplicar o valor 25 desde D0: o comunicado fixa o início da vigência em D10 e exclui a aplicação prospectiva desde D0."
  ],
  "contextos_examinados": ["CONTEXTO.ESCOPO"],
  "fundamentos_valor": {
    "valor": {
      "conhecimento": "exato",
      "valores": [25],
      "fonte_ids": ["CHANGE.D02"],
      "justificativa": "O comunicado afirma disponibilidade contratada de 25 dias corridos desde D0. Essa magnitude se aplica sob a vigência do comunicado, cujo início é D10; a aplicação desde D0 é expressamente excluída.",
      "aplicabilidade": "outro_objeto_ou_vigencia"
    }
  },
  "restricoes_escopo": [
    {
      "conhecimento": "exato",
      "valores": [10],
      "fonte_ids": ["CHANGE.D02"],
      "justificativa": "A fonte declara que o início de vigência do comunicado é D10 e exclui a aplicação prospectiva desde D0.",
      "campo": "inicio_dia"
    }
  ]
}
